        voice_settings: { stability: 0.45, similarity_boost: 0.8 }
      }));
      if (x.status === 200 && x.responseText.length > 1000) {
        var raw = x.responseText, partes = [], trozo = 8192;
        for (var i = 0; i < raw.length; i += trozo) {
          var cods = [];
          var fin = Math.min(i + trozo, raw.length);
          for (var j = i; j < fin; j++) cods.push(raw.charCodeAt(j) & 0xff);
          partes.push(String.fromCharCode.apply(null, cods));
        }
        JV.escribir(JV.AUDIO + '.b64', btoa(partes.join('')), false);
        shell('base64 -d "' + JV.AUDIO + '.b64" > "' + JV.AUDIO + '"', false, 20);
        musicPlay(JV.AUDIO, 0, false, 'media');
        ok = true;
      }
    } catch (e) { ok = false; }
  }
  if (!ok) { try { say(texto, '', '', 'media', 5, 5); } catch (e2) { flash(texto); } }
};

/* ---------- Seguridad: solo el dueño ---------- */
/* No existe verificación biométrica de voz en AutoVoice. JARVIS se protege con:
   1) Solo se activa desde perfiles de Tasker en ESTE teléfono (sin puertos abiertos).
   2) Acciones sensibles exigen el teléfono desbloqueado Y la palabra clave %JV_PIN dicha en la orden.
   3) El texto de notificaciones de terceros NUNCA se trata como orden. */
JV.SENSIBLES = { whatsapp: 1, llamar: 1, datos: 1 };
JV.bloqueado = function () { return JV.g('KEYG', 'off') === 'on'; };
JV.validarPin = function (texto) {
  var pin = JV.g('JV_PIN', '');
  if (!pin) return { ok: false, texto: texto };
  var re = new RegExp('\\b' + pin.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i');
  return { ok: re.test(texto), texto: texto.replace(re, ' ').replace(/\s+/g, ' ').trim() };
};

/* ---------- Contactos (jarvis_contactos.csv: nombre,numero con código país) ---------- */
JV.contacto = function (nombre) {
  if (/^\+?\d{8,15}$/.test(String(nombre).replace(/\s/g, ''))) return String(nombre).replace(/[\s+]/g, '');
  var t = JV.leer(JV.CONT).split('\n'), n = String(nombre).toLowerCase().trim();
  for (var i = 0; i < t.length; i++) {
    var p = t[i].split(',');
    if (p.length >= 2 && p[0].toLowerCase().trim() === n) return p[1].replace(/[\s+]/g, '');
  }
  return '';
};

/* ---------- Ejecución de acciones devueltas por el cerebro ---------- */
JV.ejecutar = function (a, pinOk) {
  var tipo = a.tipo, v = String(a.valor || ''), d = String(a.detalle || '');
  var on = /^(on|si|sí|true|1|activar|encender)$/i.test(v);
  if (JV.SENSIBLES[tipo] && (!pinOk || JV.bloqueado())) return 'bloqueada (falta palabra clave o teléfono bloqueado)';
  try {
    switch (tipo) {
      case 'abrir_app': loadApp(v, '', false); return 'ok';
      case 'alarma': {
        var hm = v.split(':');
        setAlarm(parseInt(hm[0], 10), parseInt(hm[1] || '0', 10), d || 'JARVIS', false); return 'ok';
      }
      case 'recordatorio': {
        var t = new Date(Date.now() + (parseInt(v, 10) || 10) * 60000);
        setAlarm(t.getHours(), t.getMinutes(), d || 'Recordatorio JARVIS', false); return 'ok';
      }
      case 'wifi': wifi(on); return 'ok';
      case 'datos': mobileData(on); return 'ok';
      case 'volumen': mediaVol(Math.max(0, Math.min(15, parseInt(v, 10) || 0)), false, false); return 'ok';
      case 'no_molestar': performTask('JARVIS No Molestar', 60, on ? 'on' : 'off', ''); return 'ok';
      case 'registrar_venta': JV.log('venta', parseFloat(v) || 0, d); return 'ok';
      case 'registrar_animo': JV.log('animo', parseInt(v, 10) || 0, d); return 'ok';
      case 'registrar_enfoque': JV.log('enfoque', parseInt(v, 10) || 0, d); return 'ok';
      case 'recordar': JV.escribir(JV.MEM, '\n- (' + JV.hoy() + ') ' + v + (d ? ' — ' + d : ''), true); return 'ok';
      case 'llamar': {
        var num = JV.contacto(v); if (!num) return 'contacto no encontrado';
        call('+' + num, true); return 'ok';
      }
      case 'whatsapp': {
        var tel = JV.contacto(v); if (!tel) return 'contacto no encontrado';
        performTask('JARVIS Enviar WhatsApp', 60, tel, d); return 'ok';
      }
      case 'ninguna': return 'ok';
    }
  } catch (e) { return 'error: ' + e; }
  return 'tipo desconocido';
};


/* Tarea: JARVIS Registrar  ·  %par1 = venta|animo|enfoque  ·  %par2 = "valor|detalle"
   Úsala desde widgets/atajos: p.ej. par1=venta par2=120|hoodie negro talla M */
var tipo = (typeof par1 !== 'undefined' && par1 !== '%par1') ? String(par1) : '';
var datos = (typeof par2 !== 'undefined' && par2 !== '%par2') ? String(par2).split('|') : [''];
if (/^(venta|animo|enfoque)$/.test(tipo)) {
  JV.log(tipo, datos[0], datos.slice(1).join('|'));
  var r = JV.resumenHoy();
  flash(tipo === 'venta' ? 'Venta registrada. Hoy: ' + r.ventas + ' por ' + r.monto + ' ' + JV.g('JV_MONEDA', 'S/') : 'Registrado: ' + tipo);
} else {
  flash('JARVIS Registrar: par1 debe ser venta, animo o enfoque');
}

